import { useEffect, useMemo, useState, type ReactNode } from 'react'
import { useLocation, useNavigate } from 'react-router-dom'
import type { LucideIcon } from 'lucide-react'
import {
  Activity, ArrowDown, ArrowLeft, ArrowRight, ArrowUp, ArrowUpRight, BarChart3, Bell, Check, CheckCircle2, ChevronDown,
  Clipboard, Clock3, Cloud, Copy, Database, FileText, Filter, Gauge, Globe2, HeartPulse, Info, Layers3, LifeBuoy,
  ListFilter, LockKeyhole, Menu, Network, Play, Radio, RefreshCcw, RotateCcw, Search, Server, Settings2, ShieldCheck,
  SlidersHorizontal, Sparkles, Ticket, Timer, UserRound, Users, X, Zap,
} from 'lucide-react'
import { bookingNodes as seedBookingNodes, distributedEvents, electionState as seedElectionState, flights, popularDestinations, queueNodes as seedQueueNodes, requests, scenarios, storageReplicas as seedReplicas, systemHealth, traceSteps } from './data'
import type { BackendHealth, Booking, BookingNode, DistributedEvent, Flight, LeaderElectionState, NodeStatus, QueueNode, SeatStatus, SimulationResult, StorageReplica } from './types'
import { api } from './services/api'


const money = (value: number) => `₹${value.toLocaleString('en-IN')}`
const nowLabel = () => new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })

const passengerNav = [
  { label: 'Home', path: '/', icon: Globe2 },
  { label: 'Search flights', path: '/search', icon: Search },
  { label: 'My bookings', path: '/bookings', icon: Ticket },
  { label: 'System status', path: '/status', icon: Activity },
]
const operationsNav = [
  { label: 'Overview', path: '/ops/overview', icon: Gauge },
  { label: 'Request flow', path: '/ops/flow', icon: Network },
  { label: 'Queue nodes', path: '/ops/queues', icon: Layers3 },
  { label: 'Booking nodes', path: '/ops/booking-nodes', icon: Server },
  { label: 'Replication & storage', path: '/ops/replication', icon: Database },
  { label: 'Leader election', path: '/ops/election', icon: ShieldCheck },
  { label: 'Failure simulation', path: '/ops/simulation', icon: Zap },
  { label: 'Event logs', path: '/ops/logs', icon: FileText },
]

function buildSeatMap(): Record<string, SeatStatus> {
  const map: Record<string, SeatStatus> = {}
  for (let row = 1; row <= 16; row += 1) {
    for (const column of ['A', 'B', 'C', 'D', 'E', 'F']) {
      const id = `${row}${column}`
      map[id] = ['2C', '4A', '5F', '8B', '9D', '13A', '14C', '16F'].includes(id) ? 'booked' : ['1D', '3E', '7A'].includes(id) ? 'unavailable' : 'available'
    }
  }
  return map
}

function App() {
  const location = useLocation()
  const navigate = useNavigate()
  const isOps = location.pathname.startsWith('/ops')
  const [mobileOpen, setMobileOpen] = useState(false)
  const [selectedFlightId, setSelectedFlightId] = useState('AI-201')
  const [selectedSeat, setSelectedSeat] = useState('12A')
  const [seatMap, setSeatMap] = useState<Record<string, SeatStatus>>(buildSeatMap)
  const [passengerName, setPassengerName] = useState('Aarav Mehta')
  const [passengerEmail, setPassengerEmail] = useState('aarav.mehta@example.com')
  const [bookings, setBookings] = useState<Booking[]>([])
  const [currentBooking, setCurrentBooking] = useState<Booking | null>(null)
  const [queueState, setQueueState] = useState<QueueNode[]>(seedQueueNodes)
  const [bookingState, setBookingState] = useState<BookingNode[]>(seedBookingNodes)
  const [replicaState, setReplicaState] = useState<StorageReplica[]>(seedReplicas)
  const [election, setElection] = useState<LeaderElectionState>(seedElectionState)
  const [toast, setToast] = useState('')
  const [isLiveBackend, setIsLiveBackend] = useState(false)
  const [backendHealth, setBackendHealth] = useState<BackendHealth | null>(null)
  const [flightsList, setFlightsList] = useState<Flight[]>(flights)
  const [eventsList, setEventsList] = useState<DistributedEvent[]>(distributedEvents)
  const [isSubmitting, setIsSubmitting] = useState(false)

  useEffect(() => {
    let unsub: (() => void) | undefined

    async function initBackend() {
      try {
        const health = await api.getHealth()
        if (health) {
          setBackendHealth(health)
          setIsLiveBackend(true)

          try {
            const liveFlights = await api.listFlights()
            if (liveFlights && liveFlights.length > 0) {
              setFlightsList(liveFlights)
            }
          } catch (err) {
            console.warn('[AEROLINK] Could not load live flights', err)
          }

          try {
            const liveBookings = await api.listBookings()
            if (liveBookings) {
              setBookings(liveBookings)
            }
          } catch (err) {
            console.warn('[AEROLINK] Could not load live bookings', err)
          }

          try {
            const liveEvents = await api.listEvents()
            if (liveEvents && liveEvents.length > 0) {
              setEventsList(liveEvents)
            }
          } catch (err) {
            console.warn('[AEROLINK] Could not load live events', err)
          }

          if (api.subscribeEvents) {
            unsub = api.subscribeEvents((newEvent) => {
              setEventsList((prev) => [newEvent, ...prev.filter((e) => e.id !== newEvent.id)])
              if (newEvent.type === 'booking.confirmed') {
                api.listBookings().then(setBookings).catch(() => {})
              }
            })
          }
        } else {
          setIsLiveBackend(false)
        }
      } catch {
        setIsLiveBackend(false)
      }
    }

    initBackend()

    return () => {
      if (unsub) unsub()
    }
  }, [])

  const selectedFlight = flightsList.find((flight) => flight.id === selectedFlightId) ?? flightsList[0] ?? flights[0]
  const showToast = (message: string) => {
    setToast(message)
    window.setTimeout(() => setToast(''), 2800)
  }
  const nav = (path: string) => { navigate(path); setMobileOpen(false) }
  const selectFlight = (flight: Flight) => { setSelectedFlightId(flight.id); showToast(`${flight.flightNumber} selected — choose your seat next.`) }
  const completeBooking = async () => {
    setIsSubmitting(true)
    if (isLiveBackend) {
      try {
        const booking = await api.createBooking({
          flightId: selectedFlight.id,
          passenger: passengerName || 'Demo Passenger',
          passengerEmail,
          seatId: selectedSeat,
        })
        setSeatMap((current) => ({ ...current, [selectedSeat]: 'booked' }))
        setBookings((current) => [booking, ...current.filter((b) => b.reference !== booking.reference)])
        setCurrentBooking(booking)
        showToast(`Booking ${booking.reference} confirmed by backend! Real event emitted.`)
        nav('/confirmation')
      } catch (err: any) {
        showToast(`Backend rejected: ${err.message || 'Failed to complete booking'}`)
      } finally {
        setIsSubmitting(false)
      }
    } else {
      const reference = `AL-${Math.random().toString(36).slice(2, 6).toUpperCase()}`
      const booking: Booking = { reference, flightId: selectedFlight.id, passenger: passengerName || 'Demo Passenger', seatId: selectedSeat, status: 'Confirmed', timestamp: `${new Date().toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })} · ${nowLabel()}`, provenance: 'DEMO SIMULATION', requestId: `req_${reference}` }
      setSeatMap((current) => ({ ...current, [selectedSeat]: 'booked' }))
      setBookings((current) => [booking, ...current])
      setCurrentBooking(booking)
      showToast('Demo booking confirmed locally. (Mock fallback active)')
      nav('/confirmation')
      setIsSubmitting(false)
    }
  }
  const resetDemo = () => {
    setSeatMap(buildSeatMap()); setBookings([]); setCurrentBooking(null); setQueueState(seedQueueNodes); setBookingState(seedBookingNodes); setReplicaState(seedReplicas); setElection(seedElectionState); setEventsList(distributedEvents); showToast('Demo state reset to the deterministic baseline.')
  }

  const page = renderPage(location.pathname, {
    bookings, currentBooking, selectedFlight, selectedFlightId, selectedSeat, seatMap, passengerName, passengerEmail, queueState, bookingState, replicaState, election,
    flightsList, eventsList, backendHealth, isLiveBackend, isSubmitting,
    setSelectedFlightId, setSelectedSeat, setPassengerName, setPassengerEmail, selectFlight, completeBooking, setQueueState, setBookingState, setReplicaState, setElection, nav, showToast, resetDemo,
  })


  return <div className={`app-shell ${isOps ? 'ops-shell' : 'passenger-shell'}`}>
    <aside className={`sidebar ${mobileOpen ? 'mobile-open' : ''}`}>
      <div className="brand-lockup" onClick={() => nav(isOps ? '/ops/overview' : '/')} role="button" tabIndex={0}>
        <span className="brand-mark"><span /><span /></span>
        <span><strong>AEROLINK</strong><small>reliably connected</small></span>
      </div>
      <div className="workspace-switcher">
        <span className="workspace-icon">{isOps ? <Activity size={16} /> : <Ticket size={16} />}</span>
        <div><small>Workspace</small><strong>{isOps ? 'Operations' : 'Passenger'}</strong></div>
        <ChevronDown size={15} className="muted-icon" />
        <div className="workspace-menu">
          <button onClick={() => nav('/')}><Ticket size={14} /> Passenger view</button>
          <button onClick={() => nav('/ops/overview')}><Activity size={14} /> Operations console</button>
        </div>
      </div>
      <nav className="side-nav" aria-label={isOps ? 'Operations navigation' : 'Passenger navigation'}>
        <p className="nav-label">{isOps ? 'Monitor' : 'Travel'}</p>
        {(isOps ? operationsNav : passengerNav).map((item) => <NavItem key={item.path} {...item} active={location.pathname === item.path} onClick={() => nav(item.path)} />)}
        {!isOps && <><p className="nav-label nav-label-spaced">Your account</p><NavItem label="Demo profile" path="/account" icon={UserRound} active={location.pathname === '/account'} onClick={() => nav('/account')} /></>}
      </nav>
      <div className="sidebar-bottom">
        <button className="sidebar-link" onClick={() => nav(isOps ? '/status' : '/ops/overview')}><Settings2 size={16} /> {isOps ? 'Passenger experience' : 'System console'} <ArrowUpRight size={14} /></button>
        <div className="connection-card"><span className={`pulse-dot ${isLiveBackend ? 'green' : ''}`} /><div><strong>{isLiveBackend ? 'Backend Connected' : 'Demo environment'}</strong><small>{isLiveBackend ? `${backendHealth?.service || 'aerolink-core'} (live API)` : 'Mock service fallback'}</small></div><Info size={14} /></div>
      </div>
    </aside>
    {mobileOpen && <button className="mobile-scrim" aria-label="Close menu" onClick={() => setMobileOpen(false)} />}
    <main className="shell-main">
      <header className="topbar">
        <button className="mobile-menu" aria-label="Open navigation" onClick={() => setMobileOpen(true)}><Menu size={20} /></button>
        <div className="breadcrumbs"><span>{isOps ? 'Operations console' : 'AEROLINK'}</span><ArrowRight size={13} /><strong>{pageTitle(location.pathname)}</strong></div>
        <div className="topbar-actions"><span className="demo-pill"><span className="pulse-dot" /> {isLiveBackend ? 'LIVE API (PHASE 1)' : 'DEMO MODE'}</span><button className="icon-btn" aria-label="Notifications"><Bell size={17} /></button><button className="profile-chip" onClick={() => nav('/account')}><span className="avatar">AM</span><span>Aarav</span><ChevronDown size={14} /></button></div>
      </header>

      <div className="page-wrap">{page}</div>
    </main>
    {toast && <div className="toast"><CheckCircle2 size={17} /><span>{toast}</span></div>}
  </div>
}

function NavItem({ label, path, icon: Icon, active, onClick }: { label: string; path: string; icon: LucideIcon; active: boolean; onClick: () => void }) {
  return <button className={`nav-item ${active ? 'active' : ''}`} onClick={onClick}><Icon size={17} strokeWidth={active ? 2.2 : 1.8} /><span>{label}</span>{active && <span className="nav-active-dot" />}</button>
}

function renderPage(path: string, props: PageProps) {
  if (path === '/') return <HomePage {...props} />
  if (path === '/search') return <SearchPage {...props} />
  if (path === '/seats') return <SeatSelectionPage {...props} />
  if (path === '/confirmation') return <ConfirmationPage {...props} />
  if (path === '/bookings') return <BookingsPage {...props} />
  if (path === '/status') return <StatusPage {...props} />
  if (path === '/account') return <AccountPage {...props} />
  if (path === '/ops/overview') return <OperationsOverview {...props} />
  if (path === '/ops/flow') return <RequestFlow {...props} />
  if (path === '/ops/queues') return <QueueNodesPage {...props} />
  if (path === '/ops/booking-nodes') return <BookingNodesPage {...props} />
  if (path === '/ops/replication') return <ReplicationPage {...props} />
  if (path === '/ops/election') return <ElectionPage {...props} />
  if (path === '/ops/simulation') return <SimulationPage {...props} />
  if (path === '/ops/logs') return <EventLogsPage {...props} />
  return <HomePage {...props} />
}

type PageProps = {
  bookings: Booking[]; currentBooking: Booking | null; selectedFlight: Flight; selectedFlightId: string; selectedSeat: string; seatMap: Record<string, SeatStatus>; passengerName: string; passengerEmail: string; queueState: QueueNode[]; bookingState: BookingNode[]; replicaState: StorageReplica[]; election: LeaderElectionState;
  flightsList?: Flight[]; eventsList?: DistributedEvent[]; backendHealth?: BackendHealth | null; isLiveBackend?: boolean; isSubmitting?: boolean;
  setSelectedFlightId: (id: string) => void; setSelectedSeat: (id: string) => void; setPassengerName: (value: string) => void; setPassengerEmail: (value: string) => void; selectFlight: (flight: Flight) => void; completeBooking: () => void; setQueueState: (value: QueueNode[] | ((current: QueueNode[]) => QueueNode[])) => void; setBookingState: (value: BookingNode[] | ((current: BookingNode[]) => BookingNode[])) => void; setReplicaState: (value: StorageReplica[] | ((current: StorageReplica[]) => StorageReplica[])) => void; setElection: (value: LeaderElectionState | ((current: LeaderElectionState) => LeaderElectionState)) => void; nav: (path: string) => void; showToast: (message: string) => void; resetDemo: () => void;
}


function PageIntro({ eyebrow, title, description, actions, dark = false }: { eyebrow: string; title: string; description?: string; actions?: ReactNode; dark?: boolean }) {
  return <div className={`page-intro ${dark ? 'page-intro-dark' : ''}`}><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1>{description && <p className="page-description">{description}</p>}</div>{actions && <div className="page-actions">{actions}</div>}</div>
}

function Button({ children, onClick, variant = 'primary', icon: Icon, type = 'button', disabled = false }: { children: ReactNode; onClick?: () => void; variant?: 'primary' | 'secondary' | 'ghost' | 'danger'; icon?: LucideIcon; type?: 'button' | 'submit'; disabled?: boolean }) {
  return <button type={type} disabled={disabled} className={`btn btn-${variant}`} onClick={onClick}>{Icon && <Icon size={16} />}{children}</button>
}

function StatusBadge({ status, label }: { status: string; label?: string }) {
  const normalized = status.toLowerCase().replace(/ /g, '-')
  const tone = normalized.includes('unavailable') || normalized.includes('failed') || normalized.includes('rejected') || normalized.includes('error') ? 'red' : normalized.includes('degraded') || normalized.includes('pending') || normalized.includes('recovering') || normalized.includes('queued') || normalized.includes('processing') ? 'amber' : normalized.includes('confirmed') || normalized.includes('healthy') || normalized.includes('synchronized') || normalized.includes('operational') || normalized.includes('success') ? 'green' : 'blue'
  return <span className={`status-badge ${tone}`}><span className="status-dot" />{label ?? status}</span>
}

function Provenance({ children = 'DEMO DATA' }: { children?: string }) { return <span className="provenance"><span className="provenance-dot" />{children}</span> }

function HomePage({ nav }: PageProps) {
  return <>
    <section className="hero-grid">
      <div className="hero-copy"><p className="eyebrow"><span className="eyebrow-line" /> AEROLINK / RELIABLE BY DESIGN</p><h1>Your next journey,<br /><em>without the uncertainty.</em></h1><p className="hero-lede">A calmer way to book, built to stay clear and dependable when demand gets loud.</p><div className="hero-actions"><Button icon={ArrowRight} onClick={() => nav('/search')}>Search flights</Button><Button variant="ghost" icon={Activity} onClick={() => nav('/status')}>System status</Button></div><div className="hero-proof"><span><Check size={14} /> Demo-ready booking flow</span><span><Check size={14} /> Honest system signals</span></div></div>
      <div className="hero-orbit"><div className="orbit-glow" /><div className="orbit-card orbit-card-main"><div className="orbit-card-head"><span className="mini-brand">A</span><span><strong>Peak demand, made visible.</strong><small>One request. Every handoff.</small></span><ArrowUpRight size={17} /></div><div className="route-map"><div className="route-node route-node-left"><span className="route-icon"><Users size={14} /></span><small>CLIENT</small></div><div className="route-line"><i /><i /><i /></div><div className="route-node route-node-right"><span className="route-icon"><Database size={14} /></span><small>STORAGE</small></div></div><div className="orbit-foot"><span><span className="pulse-dot" /> 99.4% request path visible</span><span className="mono">demo_0082</span></div></div><div className="orbit-card orbit-card-float"><span className="float-icon"><ShieldCheck size={16} /></span><div><strong>Seat safety first</strong><small>One seat · one decision</small></div></div><div className="orbit-tag">Every journey.<br /><strong>Reliably connected.</strong></div></div>
    </section>
    <SearchPanel nav={nav} />
    <section className="section-block destinations-block"><div className="section-heading"><div><p className="eyebrow">GO SOMEWHERE GOOD</p><h2>Popular right now</h2></div><button className="text-link" onClick={() => nav('/search')}>Explore all routes <ArrowRight size={15} /></button></div><div className="destination-grid">{popularDestinations.map((item) => <button className="destination-card" key={item.code} onClick={() => nav('/search')} style={{ backgroundImage: `linear-gradient(180deg, rgba(15,23,42,0.02) 0%, rgba(15,23,42,0.72) 100%), url(${item.image})` }}><span className="destination-code">{item.code}</span><span className="destination-info"><strong>{item.city}</strong><small>{item.meta}</small></span><span className="destination-arrow"><ArrowUpRight size={17} /></span></button>)}</div></section>
    <section className="trust-strip"><div className="trust-heading"><span className="trust-mark"><ShieldCheck size={19} /></span><div><p className="eyebrow">A BETTER KIND OF CONFIDENCE</p><h2>Clarity at every handoff.</h2></div></div><div className="trust-points"><div><strong>01</strong><span><b>Transparent by default</b><small>See what’s demo data, what’s pending, and what needs a real backend.</small></span></div><div><strong>02</strong><span><b>Seat-aware decisions</b><small>Local selections are always separate from confirmed outcomes.</small></span></div><div><strong>03</strong><span><b>Built for the rush</b><small>Trace a request from client to storage without the noise.</small></span></div></div></section>
    <footer className="site-footer"><span className="footer-brand"><span className="brand-mark small"><span /><span /></span> AEROLINK</span><span>Demo frontend · Distributed Computing project</span><span>Last updated just now · <Provenance /></span></footer>
  </>
}

function SearchPanel({ nav }: { nav: (path: string) => void }) {
  const [origin, setOrigin] = useState('BOM')
  const [destination, setDestination] = useState('DEL')
  const [roundTrip, setRoundTrip] = useState(false)
  const [date, setDate] = useState('21 Oct 2026')
  const swap = () => { setOrigin(destination); setDestination(origin) }
  return <section className="search-panel card-elevated"><div className="search-panel-head"><div><p className="eyebrow">PLAN YOUR NEXT DEPARTURE</p><h2>Where will you go?</h2></div><span className="search-demo-note"><span className="pulse-dot" /> Demo routes available</span></div><div className="trip-tabs"><button className={!roundTrip ? 'active' : ''} onClick={() => setRoundTrip(false)}>One way</button><button className={roundTrip ? 'active' : ''} onClick={() => setRoundTrip(true)}>Round trip</button></div><div className="search-fields"><Field label="From" value={origin} onChange={setOrigin} hint={origin === 'BOM' ? 'Mumbai · Chhatrapati Shivaji' : origin === 'DEL' ? 'Delhi · Indira Gandhi' : 'Select airport'} icon={<ArrowUp size={16} />} /><button className="swap-btn" onClick={swap} aria-label="Swap airports"><ArrowLeft size={15} /><ArrowRight size={15} /></button><Field label="To" value={destination} onChange={setDestination} hint={destination === 'DEL' ? 'Delhi · Indira Gandhi' : destination === 'BLR' ? 'Bengaluru · Kempegowda' : 'Select airport'} icon={<ArrowDown size={16} />} /><Field label="Departure" value={date} onChange={setDate} hint="Wednesday · Flexible dates" icon={<Clock3 size={16} />} /><Field label="Passengers" value="1 adult" onChange={() => undefined} hint="Economy" icon={<Users size={16} />} /><Button icon={Search} onClick={() => nav('/search')}>Search flights</Button></div><div className="search-panel-foot"><span><LockKeyhole size={14} /> Demo data only — no external flight API connected.</span><span>Need help? <button className="inline-button">View route guide</button></span></div></section>
}

function Field({ label, value, onChange, hint, icon }: { label: string; value: string; onChange: (value: string) => void; hint: string; icon: ReactNode }) {
  return <label className="field"><span>{label}</span><div className="field-input"><input value={value} onChange={(event) => onChange(event.target.value)} /><span className="field-icon">{icon}</span></div><small>{hint}</small></label>
}

function SearchPage({ selectedFlightId, selectFlight, nav, flightsList, isLiveBackend }: PageProps) {
  const [sort, setSort] = useState('Recommended')
  const [airline, setAirline] = useState('All airlines')
  const [priceOnly, setPriceOnly] = useState(false)
  const [showFilters, setShowFilters] = useState(false)
  const list = useMemo(() => {
    let result = [...(flightsList && flightsList.length > 0 ? flightsList : flights)]
    if (airline !== 'All airlines') result = result.filter((flight) => flight.airline === airline)
    if (priceOnly) result = result.filter((flight) => flight.price < 6500)
    if (sort === 'Price') result.sort((a, b) => a.price - b.price)
    if (sort === 'Duration') result.sort((a, b) => a.duration.localeCompare(b.duration))
    if (sort === 'Departure') result.sort((a, b) => a.departure.localeCompare(b.departure))
    return result
  }, [airline, flightsList, priceOnly, sort])
  return <><PageIntro eyebrow={isLiveBackend ? "SEARCH FLIGHTS · LIVE BACKEND INVENTORY" : "SEARCH FLIGHTS · DEMO DATA"} title="Find a better way there." description={isLiveBackend ? "Live flight offers loaded from the backend API. Select a flight to proceed with seat assignment." : "Sample routes are ready for your demo. Filters and selections are local until a backend contract is connected."} actions={<Button variant="secondary" icon={SlidersHorizontal} onClick={() => setShowFilters((value) => !value)}>Edit search</Button>} /><div className="search-summary card"><div><span className="summary-label">Your search</span><strong>Mumbai <ArrowRight size={15} /> Delhi</strong><small>21 Oct 2026 · 1 passenger · Economy</small></div><div className="summary-stat"><span>{list.length}</span><small>{isLiveBackend ? 'live flights' : 'demo flights'}</small></div><button className="summary-edit" onClick={() => setShowFilters((value) => !value)}><RefreshCcw size={15} /> Change</button></div>{showFilters && <div className="filter-drawer card"><div className="drawer-field"><label>Airline</label><select value={airline} onChange={(e) => setAirline(e.target.value)}><option>All airlines</option><option>Air India</option><option>IndiGo</option><option>Vistara</option><option>SpiceJet</option></select></div><label className="check-field"><input type="checkbox" checked={priceOnly} onChange={(e) => setPriceOnly(e.target.checked)} /><span>Show fares under ₹6,500</span></label><button className="text-link" onClick={() => { setAirline('All airlines'); setPriceOnly(false) }}>Reset filters</button></div>}<div className="results-toolbar"><div><strong>{list.length} flights</strong><span> · sorted for a calmer choice</span></div><label>Sort by <select value={sort} onChange={(e) => setSort(e.target.value)}><option>Recommended</option><option>Price</option><option>Duration</option><option>Departure</option></select></label></div><div className="flight-results">{list.length ? list.map((flight, index) => <FlightCard key={flight.id} flight={flight} selected={selectedFlightId === flight.id} onSelect={() => selectFlight(flight)} index={index} />) : <EmptyState title="No flights match" description="Reset the filters or choose a broader route to continue." action={<Button onClick={() => { setAirline('All airlines'); setPriceOnly(false) }}>Reset filters</Button>} />}</div><div className="results-footer"><Provenance>{isLiveBackend ? 'BACKEND EVENT' : 'DEMO DATA'}</Provenance> <span>{isLiveBackend ? 'Fares and seat inventory loaded from live backend service.' : 'Displayed fares are seeded demonstration values. Taxes and live inventory are not connected.'}</span><Button disabled={!selectedFlightId} onClick={() => nav('/seats')} icon={ArrowRight}>Continue to seats</Button></div></>
}


function FlightCard({ flight, selected, onSelect, index }: { flight: Flight; selected: boolean; onSelect: () => void; index: number }) {
  return <article className={`flight-card card ${selected ? 'selected' : ''}`} onClick={onSelect}><div className="flight-card-main"><div className="airline-lockup"><span className="airline-badge" style={{ background: flight.accent }}>{flight.airlineCode}</span><span><strong>{flight.airline}</strong><small>{flight.flightNumber} · {flight.cabin}</small></span></div><div className="flight-time"><strong>{flight.departure}</strong><span>{flight.origin}</span></div><div className="flight-duration"><span>{flight.duration}</span><i><b /><b /><b /></i><small>Direct</small></div><div className="flight-time"><strong>{flight.arrival}</strong><span>{flight.destination}</span></div><div className="flight-fare"><small>from</small><strong>{money(flight.price)}</strong><span>per adult</span></div></div><div className="flight-card-foot"><span className={flight.seatsLeft <= 4 ? 'low-seats' : ''}><span className="seat-mini" /> {flight.seatsLeft} seats left</span><span className="flight-card-note">{index === 0 ? 'Best balance of time and fare' : flight.stops === 0 ? 'Non-stop' : `${flight.stops} stop`}</span><span className={`select-indicator ${selected ? 'chosen' : ''}`}>{selected ? <Check size={14} /> : 'Select'}</span></div></article>
}

function SeatSelectionPage({ selectedFlight, selectedSeat, seatMap, setSelectedSeat, passengerName, passengerEmail, setPassengerName, setPassengerEmail, nav, showToast }: PageProps) {
  const seatFee = Number(selectedSeat.replace(/\D/g, '')) <= 3 ? 650 : 0
  const total = selectedFlight.price + seatFee
  const selectSeat = (id: string) => { if (seatMap[id] === 'available') { setSelectedSeat(id); showToast(`Seat ${id} selected locally — not yet confirmed.`) } }
  return <><PageIntro eyebrow="SEAT SELECTION · LOCAL STATE" title="Choose your place in the journey." description="A selected seat is local UI state. Confirmation happens only after the demo booking action below." actions={<Button variant="ghost" icon={ArrowLeft} onClick={() => nav('/search')}>Back to flights</Button>} /><div className="booking-layout"><section className="seat-card card"><div className="card-heading"><div><span className="section-kicker">{selectedFlight.flightNumber} · {selectedFlight.date}</span><h2>{selectedFlight.origin} <ArrowRight size={17} /> {selectedFlight.destination}</h2><p>{selectedFlight.departure} · {selectedFlight.duration} · {selectedFlight.airline}</p></div><StatusBadge status="DEMO DATA" label="Demo inventory" /></div><div className="seat-legend"><span><i className="seat-key available" />Available</span><span><i className="seat-key selected" />Selected</span><span><i className="seat-key booked" />Booked</span><span><i className="seat-key unavailable" />Unavailable</span></div><div className="aircraft-wrap"><div className="aircraft-nose"><span /><span /><span /></div><div className="cabin-labels"><span>WINDOW</span><span>LEFT</span><span>RIGHT</span><span>WINDOW</span></div><div className="seat-map">{Array.from({ length: 16 }, (_, rowIndex) => { const row = rowIndex + 1; return <div className="seat-row" key={row}><span className="row-number">{String(row).padStart(2, '0')}</span>{['A', 'B', 'C'].map((column) => <SeatButton key={column} id={`${row}${column}`} status={seatMap[`${row}${column}`]} selected={selectedSeat === `${row}${column}`} onClick={() => selectSeat(`${row}${column}`)} />)}<span className="aisle" />{['D', 'E', 'F'].map((column) => <SeatButton key={column} id={`${row}${column}`} status={seatMap[`${row}${column}`]} selected={selectedSeat === `${row}${column}`} onClick={() => selectSeat(`${row}${column}`)} />)}</div> })}</div><div className="aircraft-tail" /></div><div className="seat-note"><Info size={15} /><span>Seat map is seeded demo data. The backend may return different availability when integrated.</span></div></section><aside className="review-column"><section className="card passenger-form"><div className="card-heading"><div><span className="section-kicker">PASSENGER DETAILS</span><h3>Who is flying?</h3></div><UserRound size={19} className="muted-icon" /></div><label className="stacked-field"><span>Full name</span><input value={passengerName} onChange={(e) => setPassengerName(e.target.value)} /></label><label className="stacked-field"><span>Email address</span><input value={passengerEmail} onChange={(e) => setPassengerEmail(e.target.value)} type="email" /></label><div className="form-note"><ShieldCheck size={15} /><span>Demo details are kept in this session only.</span></div></section><section className="card price-card"><div className="card-heading"><div><span className="section-kicker">REVIEW</span><h3>Almost airborne.</h3></div><span className="price-total">{money(total)}</span></div><div className="review-route"><span className="review-airline" style={{ background: selectedFlight.accent }}>{selectedFlight.airlineCode}</span><div><strong>{selectedFlight.origin} → {selectedFlight.destination}</strong><small>{selectedFlight.flightNumber} · {selectedFlight.departure} · {selectedFlight.date}</small></div></div><div className="price-lines"><span><b>Base fare</b><strong>{money(selectedFlight.price)}</strong></span><span><b>Seat {selectedSeat}</b><strong>{seatFee ? money(seatFee) : 'Included'}</strong></span><span className="total-line"><b>Total demo fare</b><strong>{money(total)}</strong></span></div><Button icon={ArrowRight} onClick={() => nav('/confirmation')}>Review booking</Button><p className="under-button-note"><LockKeyhole size={13} /> No backend confirmation yet</p></section></aside></div></>
}

function SeatButton({ id, status, selected, onClick }: { id: string; status?: SeatStatus; selected: boolean; onClick: () => void }) { return <button className={`seat-button ${status ?? 'available'} ${selected ? 'selected' : ''}`} onClick={onClick} disabled={status === 'booked' || status === 'unavailable'} aria-label={`Seat ${id} ${status}`}><span>{id.replace(/[A-Z]/, '')}</span></button> }

function ConfirmationPage({ selectedFlight, selectedSeat, currentBooking, passengerName, passengerEmail, completeBooking, nav, isSubmitting }: PageProps) {
  const confirmed = Boolean(currentBooking)
  const booking = currentBooking
  const isBackend = booking?.provenance === 'BACKEND EVENT'
  return <><PageIntro eyebrow={confirmed ? (isBackend ? 'BOOKING CONFIRMED · BACKEND VERIFIED' : 'BOOKING CONFIRMED · DEMO STATE') : 'REVIEW BEFORE CONFIRMATION'} title={confirmed ? 'Your journey is taking shape.' : 'One last look, then go.'} description={confirmed ? (isBackend ? 'This booking was verified and saved by the live Node/Express backend process.' : 'This confirmation was created by the local deterministic demo. It is not a live airline reservation.') : 'Review the details below. Completing the demo booking will update this session’s seat map and My Bookings.'} actions={<Provenance>{confirmed ? (booking?.provenance || 'DEMO SIMULATION') : 'LOCAL SELECTION'}</Provenance>} /><div className="confirmation-grid"><section className={`confirmation-card ${confirmed ? 'confirmed' : 'pending'}`}><div className="confirmation-top"><div><span className="confirmation-icon">{confirmed ? <Check size={22} /> : <Clock3 size={22} />}</span><p className="eyebrow">{confirmed ? (isBackend ? 'CONFIRMED ON BACKEND' : 'CONFIRMED LOCALLY') : 'READY TO SUBMIT'}</p><h2>{confirmed ? `Booking ${booking?.reference}` : 'Your seat is selected.'}</h2><p>{confirmed ? `A verified booking record has been registered for ${booking?.passenger}.` : `Seat ${selectedSeat} is selected on ${selectedFlight.flightNumber}.`}</p></div><StatusBadge status={confirmed ? 'Confirmed' : 'Submitted'} /></div><div className="confirmation-details"><div><span>Route</span><strong>{selectedFlight.origin} → {selectedFlight.destination}</strong><small>{selectedFlight.originCity} to {selectedFlight.destinationCity}</small></div><div><span>Passenger</span><strong>{booking?.passenger ?? passengerName}</strong><small>{passengerEmail}</small></div><div><span>Departure</span><strong>{selectedFlight.date} · {selectedFlight.departure}</strong><small>{selectedFlight.duration} · Non-stop</small></div><div><span>Seat</span><strong>{selectedSeat}</strong><small>{selectedFlight.cabin} · {isBackend ? 'Backend assigned' : 'Demo inventory'}</small></div></div>{!confirmed && <Button icon={Check} onClick={completeBooking} disabled={isSubmitting}>{isSubmitting ? 'Contacting backend...' : 'Complete booking'}</Button>}{confirmed && <div className="confirmation-reference"><span>REQUEST ID</span><strong className="mono">{booking?.requestId}</strong><span>Created {booking?.timestamp}</span></div>}</section><section className="card timeline-card"><div className="card-heading"><div><span className="section-kicker">REQUEST TIMELINE</span><h3>{confirmed ? (isBackend ? 'Live backend handoff' : 'What the demo shows') : 'What will happen next'}</h3></div><Activity size={19} className="muted-icon" /></div><Timeline compact confirmed={confirmed} /><div className="timeline-provenance"><Provenance>{confirmed ? (booking?.provenance || 'DEMO SIMULATION') : 'NOT YET OCCURRED'}</Provenance><span>{confirmed ? (isBackend ? 'The backend registered this record and emitted an SSE event.' : 'The local UI updated shared state.') : 'Backend events will replace this when connected.'}</span></div><button className="text-link" onClick={() => nav('/ops/flow')}>Open request flow explorer <ArrowRight size={15} /></button></section></div><div className="confirmation-next"><button className="next-card" onClick={() => nav('/bookings')}><span className="next-icon"><Ticket size={19} /></span><span><strong>My bookings</strong><small>See records created in this session</small></span><ArrowRight size={16} /></button><button className="next-card" onClick={() => nav('/')}><span className="next-icon"><Globe2 size={19} /></span><span><strong>Plan another journey</strong><small>Return to the AEROLINK home</small></span><ArrowRight size={16} /></button></div></>
}

function Timeline({ compact = false, confirmed = false }: { compact?: boolean; confirmed?: boolean }) { const items = compact ? [['Submitted', 'Client request captured'], ['Queued', 'Queue leader admission'], ['Replicating', 'Primary-backup handoff'], ['Confirmed', confirmed ? 'Local demo state updated' : 'Awaiting booking response']] : [['Client', 'Request submitted'], ['Queue', 'Request admitted'], ['Booking', 'Seat availability checked'], ['Storage', 'Quorum acknowledgement'], ['Client', 'Response returned']]; return <div className={`timeline ${compact ? 'timeline-compact' : ''}`}>{items.map(([label, detail], index) => <div className={`timeline-item ${confirmed || index < 2 ? 'done' : ''}`} key={label + detail}><span className="timeline-marker">{confirmed || index < 2 ? <Check size={12} /> : index + 1}</span><div><strong>{label}</strong><small>{detail}</small></div>{index < items.length - 1 && <i />}</div>)}</div> }

function BookingsPage({ bookings, flightsList, nav }: PageProps) { const [query, setQuery] = useState(''); const [filter, setFilter] = useState('All'); const flist = flightsList && flightsList.length > 0 ? flightsList : flights; const filtered = bookings.filter((booking) => `${booking.reference} ${booking.flightId} ${booking.passenger}`.toLowerCase().includes(query.toLowerCase()) && (filter === 'All' || booking.status === filter)); return <><PageIntro eyebrow="MY BOOKINGS" title="Keep your journey close." description="Session and backend bookings appear here. Backend verified records are clearly distinguished." actions={<Button icon={ArrowRight} onClick={() => nav('/search')}>Book a flight</Button>} /><div className="booking-toolbar card"><label className="search-input"><Search size={16} /><input placeholder="Search reference, flight or passenger" value={query} onChange={(e) => setQuery(e.target.value)} /></label><select value={filter} onChange={(e) => setFilter(e.target.value)}><option>All</option><option>Confirmed</option><option>Pending</option><option>Rejected</option></select></div>{filtered.length ? <div className="booking-list">{filtered.map((booking) => <article className="booking-row card" key={booking.reference}><div className="booking-route-mark">{booking.flightId.split('-')[0]}</div><div className="booking-main"><div><strong>{booking.flightId}</strong><span>{flist.find((flight) => flight.id === booking.flightId)?.origin} → {flist.find((flight) => flight.id === booking.flightId)?.destination}</span></div><small>{booking.passenger} · Seat {booking.seatId}</small></div><div><span className="section-kicker">REFERENCE</span><strong className="mono">{booking.reference}</strong></div><div><StatusBadge status={booking.status} /><small>{booking.timestamp}</small></div><button className="icon-btn"><ArrowRight size={16} /></button></article>)}</div> : <EmptyState title="Your session is still open." description="No bookings match this view yet. Start with a demo route and keep the request path visible." action={<Button icon={Search} onClick={() => nav('/search')}>Find a flight</Button>} />}</> }

function StatusPage({ nav, backendHealth }: PageProps) { return <><PageIntro eyebrow={backendHealth ? "SYSTEM STATUS · LIVE BACKEND CONNECTED" : "SYSTEM STATUS · DEMO DATA"} title="A calm view of the system." description={backendHealth ? `Live process ${backendHealth.service} (v${backendHealth.version}) connected on port 3001. In-memory data store active.` : "This status page is intentionally transparent: values below are deterministic samples until a health endpoint is connected."} actions={<Button variant="secondary" icon={Activity} onClick={() => nav('/ops/overview')}>Open operations console</Button>} /><div className="status-hero card"><div className="status-hero-main"><div className="status-orb"><HeartPulse size={26} /></div><div><StatusBadge status="Operational" /><h2>{backendHealth ? `Backend ${backendHealth.service} is online` : "Core booking path is operational"}</h2><p>{backendHealth ? `Process running in ${backendHealth.environment} mode with ${backendHealth.inMemoryStore.flightsCount} flights and ${backendHealth.inMemoryStore.bookingsCount} bookings recorded.` : "Queue admission, booking coordinators, and storage replicas are represented by seeded demo data."}</p></div></div><div className="status-updated"><span>{backendHealth ? "BACKEND UPTIME" : "LAST UPDATED"}</span><strong>{backendHealth ? `${backendHealth.uptimeSeconds}s` : "Just now"}</strong><small><span className="pulse-dot" /> {backendHealth ? `${backendHealth.inMemoryStore.activeSseClients} active SSE client(s)` : "Demo heartbeat"}</small></div></div><div className="metric-grid four"><Metric icon={Layers3} label="Queue nodes" value="2 / 3" note="one degraded" tone="amber" /><Metric icon={Server} label="Booking nodes" value="3 / 4" note="one recovering" tone="amber" /><Metric icon={Database} label="Storage replicas" value="3 / 3" note="quorum available" tone="green" /><Metric icon={Timer} label="Request latency" value={backendHealth ? "12 ms" : "184 ms"} note={backendHealth ? "live backend loop" : "p95 · demo sample"} tone="blue" /></div><section className="card status-explainer"><div><p className="eyebrow">WHY THIS MATTERS</p><h2>Reliable does not mean invisible.</h2><p>The passenger view stays simple, while the operations view explains the handoffs that make a distributed booking workflow understandable during a rush.</p></div><div className="mini-flow"><span>Client</span><ArrowRight size={15} /><span>Queue</span><ArrowRight size={15} /><span>Booking</span><ArrowRight size={15} /><span>Storage</span></div></section></> }


function AccountPage({ resetDemo, nav }: PageProps) { return <><PageIntro eyebrow="DEMO PROFILE" title="A small profile for a big system." description="This profile is local to the demo session. No account or identity service is connected." actions={<Button variant="danger" icon={RotateCcw} onClick={resetDemo}>Reset demo state</Button>} /><div className="account-grid"><section className="card profile-card"><div className="profile-avatar">AM</div><div><p className="eyebrow">PASSENGER PROFILE</p><h2>Aarav Mehta</h2><p>aarav.mehta@example.com</p><div className="profile-tags"><span><Check size={13} /> Demo profile</span><span><Cloud size={13} /> Session only</span></div></div></section><section className="card account-settings"><div className="card-heading"><div><span className="section-kicker">PREFERENCES</span><h3>Experience settings</h3></div><Settings2 size={18} className="muted-icon" /></div><div className="setting-row"><span><strong>Workspace on launch</strong><small>Passenger view keeps the main booking flow close.</small></span><button className="toggle on"><span /></button></div><div className="setting-row"><span><strong>Show demo provenance</strong><small>Always label simulated values and events.</small></span><button className="toggle on"><span /></button></div><div className="setting-row"><span><strong>Operations console</strong><small>Trace the distributed request path.</small></span><button className="text-link" onClick={() => nav('/ops/overview')}>Open console <ArrowRight size={14} /></button></div></section></div></> }

function OperationsOverview({ queueState, bookingState, replicaState, nav }: PageProps) { const [selected, setSelected] = useState<string | null>(null); const activeQueues = queueState.filter((node) => node.status !== 'unavailable').length; const activeBookings = bookingState.filter((node) => node.status !== 'unavailable').length; const activeReplicas = replicaState.filter((node) => node.status !== 'unavailable').length; return <><PageIntro dark eyebrow="OPERATIONS CONSOLE · OVERVIEW" title="See the system think." description="A topology-first view of the distributed booking path. Metrics are deterministic demo values until connected to a real health stream." actions={<div className="intro-status"><span className="pulse-dot" /> <strong>Operational</strong><small>updated just now</small></div>} /><div className="ops-banner"><span className="ops-banner-icon"><Activity size={18} /></span><div><strong>DEMO OBSERVABILITY LAYER</strong><p>Every node state, metric, and event on this screen is labeled demo data until a backend stream is connected.</p></div><button className="text-link" onClick={() => nav('/ops/logs')}>View event logs <ArrowRight size={14} /></button></div><div className="metric-grid ops-metrics"><OpsMetric label="System status" value="Operational" note="All core paths available" icon={HeartPulse} tone="green" /><OpsMetric label="Queue depth" value={String(systemHealth.queueDepth)} note="+8 since last sample" icon={Layers3} tone="blue" /><OpsMetric label="Requests processed" value="8,214" note="sampled over 24h" icon={BarChart3} tone="blue" /><OpsMetric label="Successful bookings" value="6,948" note="83 rejected requests" icon={Ticket} tone="green" /></div><section className="topology-panel"><div className="topology-heading"><div><p className="eyebrow">REQUEST PATH</p><h2>From intent to durable state.</h2></div><div className="topology-legend"><span><i className="legend-dot green" />Healthy</span><span><i className="legend-dot amber" />Degraded</span><span><i className="legend-dot blue" />Flow direction</span></div></div><Topology queueState={queueState} bookingState={bookingState} replicaState={replicaState} selected={selected} onSelect={setSelected} /></section>{selected && <NodeDetail nodeId={selected} queueState={queueState} bookingState={bookingState} replicaState={replicaState} onClose={() => setSelected(null)} />}</> }

function OpsMetric({ label, value, note, icon: Icon, tone }: { label: string; value: string; note: string; icon: LucideIcon; tone: string }) { return <div className="ops-metric"><div className="ops-metric-top"><span>{label}</span><span className={`metric-icon ${tone}`}><Icon size={16} /></span></div><strong>{value}</strong><small>{note}</small></div> }
function Metric({ label, value, note, icon: Icon, tone }: { label: string; value: string; note: string; icon: LucideIcon; tone: string }) { return <div className="metric-card card"><span className={`metric-icon ${tone}`}><Icon size={16} /></span><span className="metric-label">{label}</span><strong>{value}</strong><small>{note}</small></div> }

function Topology({ queueState, bookingState, replicaState, selected, onSelect }: { queueState: QueueNode[]; bookingState: BookingNode[]; replicaState: StorageReplica[]; selected: string | null; onSelect: (id: string) => void }) { const layers = [{ label: 'CLIENTS', icon: Users, nodes: [{ id: 'client-gateway', name: 'Passenger app', meta: 'request origin', status: 'healthy' as NodeStatus }] }, { label: 'LOAD BALANCER', icon: Network, nodes: [{ id: 'lb-01', name: 'Round Robin', meta: 'routing layer', status: 'healthy' as NodeStatus }] }, { label: 'QUEUE LAYER', icon: Layers3, nodes: queueState.map((node) => ({ id: node.id, name: node.id, meta: node.isLeader ? 'leader · admission' : 'admission node', status: node.status })) }, { label: 'BOOKING LAYER', icon: Server, nodes: bookingState.map((node) => ({ id: node.id, name: node.id, meta: `${node.role} · ${node.shard}`, status: node.status })) }, { label: 'STORAGE LAYER', icon: Database, nodes: replicaState.map((node) => ({ id: node.id, name: node.id.replace('replica-', 'Replica '), meta: node.sync.toLowerCase(), status: node.status })) }]; return <div className="topology-scroll"><div className="topology-grid">{layers.map((layer, layerIndex) => <div className="topology-layer" key={layer.label}><div className="topology-layer-label"><layer.icon size={13} /> {layer.label}</div><div className="topology-nodes">{layer.nodes.map((node) => <button key={node.id} className={`topology-node ${node.status} ${selected === node.id ? 'selected' : ''}`} onClick={() => onSelect(node.id)}><span className="node-status"><span /></span><strong>{node.name}</strong><small>{node.meta}</small>{node.id === 'queue-01' && <em>LEADER</em>}{'role' in node && node.role === 'primary' && <em>PRIMARY</em>}</button>)}</div>{layerIndex < layers.length - 1 && <div className="topology-connector"><ArrowRight size={15} /><span>handoff</span></div>}</div>)}</div><div className="topology-caption"><span><Info size={14} /> Click any node to inspect its role, status, and recent events.</span><Provenance /></div></div> }

function NodeDetail({ nodeId, queueState, bookingState, replicaState, onClose }: { nodeId: string; queueState: QueueNode[]; bookingState: BookingNode[]; replicaState: StorageReplica[]; onClose: () => void }) { const node = queueState.find((item) => item.id === nodeId); const booking = bookingState.find((item) => item.id === nodeId); const replica = replicaState.find((item) => item.id === nodeId); const status = node?.status ?? booking?.status ?? replica?.status ?? 'healthy'; return <aside className="node-detail card"><button className="icon-btn close-btn" onClick={onClose}><X size={17} /></button><span className="section-kicker">NODE INSPECTOR</span><h3 className="mono">{nodeId}</h3><StatusBadge status={status} /><div className="detail-list">{node && <><Detail label="Role" value={node.isLeader ? 'Queue leader' : 'Queue node'} /><Detail label="Queue depth" value={String(node.queueDepth)} /><Detail label="Processed" value={node.processed.toLocaleString()} /><Detail label="Heartbeat" value={node.heartbeat} /></>}{booking && <><Detail label="Role" value={`${booking.role} · ${booking.shard}`} /><Detail label="Flight group" value={booking.flightGroup} /><Detail label="Processed" value={booking.processed.toLocaleString()} /><Detail label="Replication" value={booking.replication} /></>}{replica && <><Detail label="Version" value={replica.version} /><Detail label="Latest write" value={replica.latestWrite} /><Detail label="Sync" value={replica.sync} /></>}</div><div className="detail-event"><span className="event-severity info">INFO</span><p>Latest sample indicates this node remains visible to the demo topology.</p><small>Just now · {nodeId}</small></div></aside> }
function Detail({ label, value }: { label: string; value: string }) { return <div className="detail-row"><span>{label}</span><strong>{value}</strong></div> }

function RequestFlow(_props: PageProps) { const [requestId, setRequestId] = useState(requests[0].id); const request = requests.find((item) => item.id === requestId) ?? requests[0]; return <><PageIntro dark eyebrow="REQUEST FLOW EXPLORER" title="Follow one request all the way through." description="A chronological trace makes the distributed architecture explainable. The current events are deterministic demo data." actions={<Provenance>DEMO DATA</Provenance>} /><div className="trace-toolbar"><label><Search size={15} /><select value={requestId} onChange={(e) => setRequestId(e.target.value)}>{requests.map((item) => <option key={item.id} value={item.id}>{item.id} · {item.flightId} · seat {item.seatId}</option>)}</select></label><div className="trace-summary"><span><span className="section-kicker">FINAL RESULT</span><StatusBadge status={request.status} /></span><span><span className="section-kicker">LAMPORT CLOCK</span><strong className="mono">{request.logicalClock}</strong></span></div></div><div className="trace-layout"><section className="trace-panel"><div className="trace-heading"><div><p className="eyebrow">CHRONOLOGICAL HANDOFFS</p><h2>{request.id}</h2></div><span className="mono trace-seat">{request.flightId} / {request.seatId}</span></div><div className="trace-steps">{traceSteps.map(([index, title, actor, detail], stepIndex) => <div className="trace-step" key={index}><div className={`trace-step-marker ${stepIndex < 7 ? 'complete' : ''}`}><span>{index}</span></div><div className="trace-step-copy"><div><strong>{title}</strong><span>{actor}</span></div><p>{detail}</p><small>{stepIndex < 7 ? <><Check size={12} /> demo event · 09:4{8 - Math.min(stepIndex, 7)}:{String(6 + stepIndex).padStart(2, '0')}</> : 'not yet occurred'}</small></div>{stepIndex < traceSteps.length - 1 && <i />}</div>)}</div></section><aside className="trace-side"><section className="card"><div className="card-heading"><div><span className="section-kicker">REQUEST CONTEXT</span><h3>What we know</h3></div><Info size={18} className="muted-icon" /></div><Detail label="Request ID" value={request.id} /><Detail label="Flight / seat" value={`${request.flightId} · ${request.seatId}`} /><Detail label="Queue node" value={request.queueNode} /><Detail label="Booking node" value={request.bookingNode} /><Detail label="Logical timestamp" value={String(request.logicalClock)} /><div className="form-note"><Info size={14} /><span>Actual backend events will replace demo events when the API is connected.</span></div></section><section className="card"><div className="card-heading"><div><span className="section-kicker">PROVENANCE</span><h3>Read it honestly.</h3></div></div><div className="provenance-list"><div><Provenance>BACKEND EVENT</Provenance><small>Only shown when returned by the service.</small></div><div><Provenance>DEMO DATA</Provenance><small>Seeded sample used to explain the path.</small></div><div><Provenance>NOT YET OCCURRED</Provenance><small>No claim is made about future events.</small></div></div></section></aside></div></> }

function QueueNodesPage({ queueState, setQueueState, showToast }: PageProps) { const toggle = (id: string) => { setQueueState((current) => current.map((node) => node.id === id ? { ...node, status: node.status === 'unavailable' ? 'recovering' : 'unavailable', heartbeat: node.status === 'unavailable' ? 'rejoining now' : 'failure simulated' } : node)); showToast('Queue state changed in demo mode only. Backend nodes were not touched.') }; const available = queueState.filter((node) => node.status !== 'unavailable'); return <><PageIntro dark eyebrow="QUEUE NODES · ROUND ROBIN" title="Admission that keeps moving." description="Watch how the queue layer distributes requests across available nodes. This page’s controls are isolated demo simulation." actions={<Provenance>DEMO SIMULATION</Provenance>} /><div className="queue-summary"><div><span className="section-kicker">CURRENT LEADER</span><strong className="mono">{queueState.find((node) => node.isLeader)?.id ?? 'awaiting election'}</strong><small>heartbeat · {queueState.find((node) => node.isLeader)?.heartbeat ?? '—'}</small></div><div><span className="section-kicker">AVAILABLE NODES</span><strong>{available.length} / {queueState.length}</strong><small>Round Robin skips unavailable nodes</small></div><div><span className="section-kicker">QUEUE DEPTH</span><strong>{queueState.reduce((sum, node) => sum + node.queueDepth, 0)}</strong><small>sampled request backlog</small></div></div><div className="dark-card-grid">{queueState.map((node) => <section className="node-card dark-card" key={node.id}><div className="node-card-top"><div><span className="node-icon"><Layers3 size={17} /></span><h3 className="mono">{node.id}</h3></div><StatusBadge status={node.status} /></div><div className="leader-label">{node.isLeader ? <><ShieldCheck size={14} /> CURRENT LEADER</> : <><Radio size={14} /> ADMISSION NODE</>}</div><div className="node-stat-grid"><Detail label="Queue depth" value={String(node.queueDepth)} /><Detail label="Received" value={node.received.toLocaleString()} /><Detail label="Processed" value={node.processed.toLocaleString()} /><Detail label="Heartbeat" value={node.heartbeat} /></div><div className="node-card-foot"><span><span className={`status-dot ${node.status}`} /> {node.status === 'unavailable' ? 'Skipped by router' : 'Receiving requests'}</span><Button variant="ghost" onClick={() => toggle(node.id)} icon={node.status === 'unavailable' ? RefreshCcw : Zap}>{node.status === 'unavailable' ? 'Recover node' : 'Simulate failure'}</Button></div></section>)}</div><section className="round-robin card"><div className="card-heading"><div><span className="section-kicker">ROUTING SEQUENCE</span><h2>Round Robin, made legible.</h2><p>Healthy nodes receive requests in order. A node marked unavailable is skipped in this local simulation.</p></div><span className="rr-index">next · <strong>queue-02</strong></span></div><div className="rr-track">{[...available, ...available, ...available].slice(0, 8).map((node, index) => <div className="rr-step" key={`${node.id}-${index}`}><span>{String(index + 1).padStart(2, '0')}</span><strong>{node.id}</strong>{index < 7 && <ArrowRight size={14} />}</div>)}</div><div className="card-foot-note"><Provenance>DEMO SIMULATION</Provenance><span>Routing visualization is separate from actual backend operations.</span></div></section></> }

function BookingNodesPage({ bookingState, setBookingState, showToast }: PageProps) { const recover = (id: string) => { setBookingState((current) => current.map((node) => node.id === id ? { ...node, status: 'healthy', replication: 'Synchronized', syncedAt: 'just now' } : node)); showToast(`${id} marked synchronized in demo mode.`) }; const groups = [...new Set(bookingState.map((node) => node.shard))]; return <><PageIntro dark eyebrow="BOOKING NODES · SHARDS" title="A decision, then a durable handoff." description="Primary and backup nodes are grouped by flight shard so the consistency policy stays visible." actions={<Provenance>DEMO DATA</Provenance>} /><div className="shard-grid">{groups.map((shard) => <section className="shard-card dark-card" key={shard}><div className="shard-heading"><div><span className="section-kicker">FLIGHT SHARD</span><h2 className="mono">{shard}</h2></div><span className="shard-flight">{bookingState.find((node) => node.shard === shard)?.flightGroup}</span></div><div className="replication-line"><span className="replication-node primary"><Server size={16} /><strong>Primary</strong><small>{bookingState.find((node) => node.shard === shard && node.role === 'primary')?.id}</small></span><div className="replication-connector"><span>update</span><ArrowRight size={16} /><span>ack</span></div><span className="replication-node backup"><Database size={16} /><strong>Backup</strong><small>{bookingState.find((node) => node.shard === shard && node.role === 'backup')?.id}</small></span></div><div className="shard-nodes">{bookingState.filter((node) => node.shard === shard).map((node) => <div className="shard-node" key={node.id}><div><strong className="mono">{node.id}</strong><small>{node.role} · {node.processed.toLocaleString()} processed</small></div><div><StatusBadge status={node.replication} /><small>synced {node.syncedAt}</small></div>{node.status !== 'healthy' && <Button variant="ghost" onClick={() => recover(node.id)} icon={RefreshCcw}>Recover</Button>}</div>)}</div><div className="shard-note"><CheckCircle2 size={14} /> Primary checks seat → update sent → acknowledgement received → response returned.</div></section>)}</div><section className="replication-policy card"><div className="policy-icon"><Layers3 size={19} /></div><div><p className="eyebrow">CONSISTENCY POLICY</p><h2>Show the subset you actually need.</h2><p>This demo visualizes a primary-backup relationship. It does not imply that every replica acknowledges every write when a backend policy only requires a subset.</p></div></section></> }

function ReplicationPage({ replicaState, setReplicaState, showToast }: PageProps) { const [run, setRun] = useState(false); const quorum = replicaState.filter((replica) => replica.acknowledged && replica.status !== 'unavailable').length >= 2; const toggleReplica = (id: string) => { setReplicaState((current) => current.map((replica) => replica.id === id ? { ...replica, status: replica.status === 'unavailable' ? 'healthy' : 'unavailable', acknowledged: replica.status === 'unavailable' } : replica)); showToast('Replica state changed in demo mode only.') }; return <><PageIntro dark eyebrow="REPLICATION & STORAGE · QUORUM" title="A majority makes the decision durable." description="A three-replica example showing how a 2-of-3 quorum can gate a booking update." actions={<Provenance>DEMO SIMULATION</Provenance>} /><div className="quorum-hero"><div className="quorum-copy"><span className="quorum-fraction">{replicaState.filter((replica) => replica.acknowledged).length}<small>/ 3</small></span><div><p className="eyebrow">CURRENT ACKNOWLEDGEMENTS</p><h2>{quorum ? 'Quorum condition met.' : 'Quorum condition not met.'}</h2><p>{quorum ? 'The configured demo policy permits confirmation with two of three replicas acknowledging.' : 'The demo policy keeps confirmation pending until a majority acknowledges.'}</p></div></div><div className={`quorum-seal ${quorum ? 'met' : ''}`}>{quorum ? <Check size={25} /> : <Clock3 size={25} />}<span>{quorum ? '2 / 3 majority' : 'awaiting majority'}</span></div></div><div className="replica-grid">{replicaState.map((replica, index) => <section className="replica-card dark-card" key={replica.id}><div className="replica-top"><span className="replica-letter">{String.fromCharCode(65 + index)}</span><StatusBadge status={replica.status} /></div><h3>{replica.id.replace('replica-', 'Replica ')}</h3><div className="replica-version"><span>VERSION</span><strong className="mono">{replica.version}</strong></div><div className="replica-details"><Detail label="Latest write" value={replica.latestWrite} /><Detail label="Sync" value={replica.sync} /></div><div className="replica-actions"><span>{replica.acknowledged ? <><Check size={13} /> Acknowledged</> : <><Clock3 size={13} /> Awaiting write</>}</span><button onClick={() => toggleReplica(replica.id)}>{replica.status === 'unavailable' ? 'Restore' : 'Set unavailable'}</button></div></section>)}</div><section className="write-progress card"><div className="card-heading"><div><span className="section-kicker">WRITE PROGRESSION</span><h2>Booking update → confirmation gate</h2></div><Button onClick={() => setRun((value) => !value)} icon={run ? RotateCcw : Play}>{run ? 'Reset progression' : 'Run quorum demo'}</Button></div><div className="progress-steps">{['Booking update initiated', 'Replica acknowledgements received', 'Quorum condition evaluated', quorum ? 'Confirmation permitted' : 'Confirmation pending'].map((label, index) => <div className={`progress-step ${run || index < 2 ? 'active' : ''}`} key={label}><span>{run || index < 2 ? <Check size={13} /> : index + 1}</span><strong>{label}</strong>{index < 3 && <i />}</div>)}</div><div className="card-foot-note"><Provenance>DEMO SIMULATION</Provenance><span>A production-connected view must derive these states from actual acknowledgements.</span></div></section></> }

function ElectionPage({ election, setElection, showToast }: PageProps) { const [algorithm, setAlgorithm] = useState(election.algorithm); const [layer, setLayer] = useState(election.layer); const runElection = () => { const newLeader = election.currentLeader === 'queue-01' ? 'queue-02' : 'queue-01'; setElection((current) => ({ ...current, currentLeader: newLeader, electionId: `election_${Math.floor(Math.random() * 100).toString().padStart(4, '0')}`, algorithm, layer, history: [{ time: nowLabel(), event: 'New leader selected in demo', node: newLeader, tone: 'SUCCESS' }, { time: nowLabel(), event: 'Election progression visualized', node: current.currentLeader, tone: 'INFO' }, ...current.history] })); showToast('Election progression visualized in demo mode only.') }; return <><PageIntro dark eyebrow="LEADER ELECTION · FAULT TOLERANCE" title="When leadership changes, the story should stay clear." description="Switch between the queue layer and a booking shard. The UI visualizes protocol concepts; the backend remains responsible for election results." actions={<Provenance>DEMO SIMULATION</Provenance>} /><div className="election-controls card"><div className="segmented"><button className={layer === 'Queue layer' ? 'active' : ''} onClick={() => setLayer('Queue layer')}>Queue layer</button><button className={layer === 'Booking layer' ? 'active' : ''} onClick={() => setLayer('Booking layer')}>Booking layer</button></div><div className="segmented"><button className={algorithm === 'Bully' ? 'active' : ''} onClick={() => setAlgorithm('Bully')}>Bully</button><button className={algorithm === 'Ring' ? 'active' : ''} onClick={() => setAlgorithm('Ring')}>Ring</button></div><Button icon={Play} onClick={runElection}>Run election demo</Button></div><div className="election-grid"><section className="election-visual dark-card"><div className="election-visual-head"><div><span className="section-kicker">{layer.toUpperCase()}</span><h2>{algorithm} progression</h2></div><span className="election-id mono">{election.electionId}</span></div><div className="election-ring">{['queue-01', 'queue-02', 'queue-03'].map((node, index) => <div className={`election-node ${node === election.currentLeader ? 'leader' : ''} ${index === 2 ? 'degraded' : ''}`} key={node}><span>{index + 1}</span><strong>{layer === 'Queue layer' ? node : `book-0${index + 1}`}</strong><small>{node === election.currentLeader ? 'CURRENT LEADER' : index === 2 ? 'HEARTBEAT LATE' : `priority ${30 - index * 10}`}</small></div>)}<div className="election-center"><ShieldCheck size={20} /><strong>{election.currentLeader}</strong><small>elected leader</small></div></div><div className="election-callout"><Info size={15} /><span>{algorithm === 'Bully' ? 'Highest-priority available node is shown as the election winner.' : 'Ring progression is shown as an ordered handoff around the active nodes.'}</span></div></section><section className="election-history card"><div className="card-heading"><div><span className="section-kicker">ELECTION HISTORY</span><h3>What the system observed</h3></div><Clock3 size={18} className="muted-icon" /></div><div className="history-list">{election.history.map((item, index) => <div className="history-item" key={`${item.time}-${index}`}><span className={`history-icon ${item.tone.toLowerCase()}`}>{item.tone === 'SUCCESS' ? <Check size={13} /> : item.tone === 'WARN' ? <Bell size={13} /> : <Radio size={13} />}</span><div><strong>{item.event}</strong><small>{item.time} · <span className="mono">{item.node}</span></small></div></div>)}</div><div className="form-note"><Info size={14} /><span>Frontend visualization only; election protocol execution belongs to the backend.</span></div></section></div></> }

function SimulationPage({ queueState, replicaState, setQueueState, setReplicaState, showToast, resetDemo }: PageProps) { const [scenarioId, setScenarioId] = useState('same-seat'); const [result, setResult] = useState<SimulationResult | null>(null); const scenario = scenarios.find((item) => item.id === scenarioId) ?? scenarios[0]; const run = () => { const steps = scenario.evidence.map((line) => `Demo event: ${line}`); setResult({ scenarioId, running: false, complete: true, steps, finalState: scenario.outcome, tone: scenario.id === 'same-seat' || scenario.id === 'replica-down' ? 'SUCCESS' : 'INFO' }); if (scenario.id === 'queue-failure') setQueueState((current) => current.map((node) => node.id === 'queue-03' ? { ...node, status: 'unavailable' } : node)); if (scenario.id === 'replica-down') setReplicaState((current) => current.map((replica) => replica.id === 'replica-c' ? { ...replica, status: 'unavailable', acknowledged: false } : replica)); showToast('Simulation completed locally. No backend state was changed.') }; const reset = () => { setResult(null); resetDemo() }; return <><PageIntro dark eyebrow="FAILURE SIMULATION LAB" title="Make the hard moments explainable." description="An isolated workspace for deterministic scenarios. Run a test, inspect the visible steps, then reset without touching backend infrastructure." actions={<span className="demo-label"><Zap size={14} /> DEMO SIMULATION</span>} /><div className="simulation-layout"><section className="scenario-list dark-card"><div className="scenario-list-head"><div><span className="section-kicker">SCENARIOS</span><h2>Choose a test</h2></div><span className="scenario-count">{scenarios.length} ready</span></div>{scenarios.map((item) => <button key={item.id} className={`scenario-item ${scenario.id === item.id ? 'active' : ''}`} onClick={() => { setScenarioId(item.id); setResult(null) }}><span className="scenario-number">{String(scenarios.indexOf(item) + 1).padStart(2, '0')}</span><span><strong>{item.name}</strong><small>{item.eyebrow}</small></span><ArrowRight size={15} /></button>)}</section><section className="simulation-main"><div className="card scenario-detail"><div className="scenario-detail-head"><div><p className="eyebrow">{scenario.eyebrow}</p><h2>{scenario.name}</h2><p>{scenario.description}</p></div><div className="scenario-focus"><span>TESTING</span><strong>{scenario.focus}</strong></div></div><div className="sim-topology"><span className="sim-node"><Users size={16} /> Client</span><ArrowRight size={15} /><span className="sim-node"><Layers3 size={16} /> Queue</span><ArrowRight size={15} /><span className="sim-node"><Server size={16} /> Booking</span><ArrowRight size={15} /><span className="sim-node"><Database size={16} /> Storage</span></div><div className="simulation-actions"><Button icon={Play} onClick={run}>Run simulation</Button><Button variant="secondary" icon={RotateCcw} onClick={reset}>Reset scenario</Button><Provenance>DEMO SIMULATION</Provenance></div></div>{result ? <section className="card result-panel"><div className="result-head"><div><span className="section-kicker">RESULT</span><h2>{result.tone === 'SUCCESS' ? 'No hidden failures.' : 'The transition is visible.'}</h2></div><StatusBadge status={result.tone === 'SUCCESS' ? 'SUCCESS' : 'INFO'} label={result.tone === 'SUCCESS' ? 'Expected outcome' : 'Observed outcome'} /></div><div className="result-steps">{result.steps.map((step, index) => <div key={step}><span><Check size={13} /></span><strong>{String(index + 1).padStart(2, '0')}</strong><p>{step}</p></div>)}</div><div className="outcome-box"><span className="section-kicker">FINAL STATE</span><strong>{result.finalState}</strong><small>Evidence is local to this demo and should be replaced by backend results when connected.</small></div></section> : <section className="card empty-simulation"><span className="empty-icon"><Play size={19} /></span><h3>Ready when you are.</h3><p>Run “{scenario.name}” to reveal the step-by-step state changes and outcome evidence.</p></section>}</section></div></> }

function EventLogsPage(props: PageProps) { const [query, setQuery] = useState(''); const [severity, setSeverity] = useState('All'); const [expanded, setExpanded] = useState<string | null>(null); const [copied, setCopied] = useState(false); const sourceEvents = props.eventsList && props.eventsList.length > 0 ? props.eventsList : distributedEvents; const filtered = sourceEvents.filter((event) => (severity === 'All' || event.severity === severity) && `${event.message} ${event.type} ${event.nodeId} ${event.requestId}`.toLowerCase().includes(query.toLowerCase())); const copy = (event: DistributedEvent) => { navigator.clipboard?.writeText(JSON.stringify(event, null, 2)); setCopied(true); window.setTimeout(() => setCopied(false), 1600) }; return <><PageIntro dark eyebrow="EVENT LOGS" title="A readable record of every handoff." description={props.isLiveBackend ? "Real-time backend event stream active via Server-Sent Events (SSE). Live events are marked with BACKEND EVENT." : "Filter the technical stream without turning it into a wall of text. Current entries are seeded demo events."} actions={<Provenance>{props.isLiveBackend ? 'BACKEND EVENT STREAM ACTIVE' : 'DEMO DATA'}</Provenance>} /><div className="logs-toolbar"><label className="logs-search"><Search size={16} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search message, node, request ID..." /></label><select value={severity} onChange={(e) => setSeverity(e.target.value)}><option>All</option><option>INFO</option><option>SUCCESS</option><option>WARN</option><option>ERROR</option></select><span className="log-count"><span className="pulse-dot" /> {filtered.length} events</span></div><section className="logs-table dark-card"><div className="logs-head"><span>TIME</span><span>SEVERITY</span><span>EVENT / REQUEST</span><span>NODE</span><span>MESSAGE</span><span /></div>{filtered.length ? filtered.map((event) => <div className={`log-row ${expanded === event.id ? 'expanded' : ''}`} key={event.id}><div className="log-time mono">{event.timestamp}<small>UTC +05:30</small></div><div><span className={`event-severity ${event.severity.toLowerCase()}`}>{event.severity}</span></div><div><strong className="mono">{event.type}</strong><small className="mono">{event.requestId}</small></div><div className="mono">{event.nodeId}<small>clock {event.logicalClock ?? event.sequence ?? '—'}</small></div><div><p>{event.message}</p><small><Provenance>{event.provenance}</Provenance></small></div><div className="log-actions"><button className="icon-btn" aria-label="Copy event details" onClick={() => copy(event)}><Copy size={15} /></button><button className="icon-btn" aria-label="Expand event" onClick={() => setExpanded(expanded === event.id ? null : event.id)}>{expanded === event.id ? <ChevronDown size={15} /> : <ArrowRight size={15} />}</button>{expanded === event.id && <div className="log-detail"><p>{event.details}</p><button className="text-link" onClick={() => copy(event)}>{copied ? 'Copied' : 'Copy event details'} <Clipboard size={13} /></button></div>}</div></div>) : <EmptyState title="No events match" description="Try a different severity or search term." action={<Button onClick={() => { setQuery(''); setSeverity('All') }}>Clear filters</Button>} />}</section></> }


function EmptyState({ title, description, action }: { title: string; description: string; action?: ReactNode }) { return <div className="empty-state"><span className="empty-icon"><Info size={20} /></span><h3>{title}</h3><p>{description}</p>{action}</div> }
function pageTitle(path: string) { const match = [...passengerNav, { label: 'Seat selection', path: '/seats' }, { label: 'Booking confirmation', path: '/confirmation' }, ...operationsNav, { label: 'Demo profile', path: '/account' }].find((item) => item.path === path); return match?.label ?? 'Overview' }

export default App
